type AdultTopicClassData = {
  id: string;
  title: string;
  description: string;
  objective: string;
  imageUrl: string;
  videoUrl: string;
  welcome: [string, string, string];
  warmup: [string, string, string];
  goals: [string, string, string];
  core: [string, string, string];
  vocab: [string, string, string, string];
  notes: [string, string, string];
  models: [string, string, string];
  context: [string, string, string];
  checks: [ReturnType<typeof quiz>, ReturnType<typeof quiz>, ReturnType<typeof quiz>];
  emoji: { content: [string]; options: [string, string, string]; correctOptionIndex: 0 | 1 | 2 };
  talk: [string, string, string];
  funChecks: [ReturnType<typeof quiz>, ReturnType<typeof quiz>, ReturnType<typeof quiz>];
  share: [string, string, string];
  summary: [string, string, string];
  homework: [string, string, string];
};

function buildAdultTopicClass(data: AdultTopicClassData): CurriculumClass {
  return buildBlueprintClass({
    id: data.id,
    title: data.title,
    description: data.description,
    objective: data.objective,
    welcome: { title: `${data.title} / Inicio`, content: data.welcome, imageUrl: data.imageUrl },
    warmup: { title: 'Warm-up / Activacion', content: data.warmup },
    goals: data.goals,
    grammarSlides: [
      { title: 'Core Idea / Idea central', content: data.core },
      { title: 'Key Vocabulary / Vocabulario', content: data.vocab },
      { title: 'Useful Notes / Notas utiles', content: data.notes },
      { title: 'Model Language / Modelo', content: data.models, imageUrl: data.imageUrl },
      { title: 'Common Use / Uso comun', content: data.context },
    ],
    context: { title: 'Context / Contexto', content: data.context, imageUrl: data.imageUrl },
    checks: data.checks,
    emoji: { prompt: 'Emoji Mission / Mision Emoji', content: data.emoji.content, options: data.emoji.options, correctOptionIndex: data.emoji.correctOptionIndex },
    talk: { title: "Let's Talk! / A hablar", content: data.talk, imageUrl: data.imageUrl },
    funChecks: data.funChecks,
    share: { title: 'Share and Extend / Comparte', content: data.share, imageUrl: data.imageUrl },
    summary: { title: 'Wrap-up / Cierre', content: data.summary, imageUrl: data.imageUrl },
    homework: data.homework,
    video: { url: data.videoUrl, content: ['Listen for one key expression.', 'Write one useful sentence from the video.', 'Bring one spoken example next class.'] },
  });
}

