const adultClassOverrides: Record<string, CurriculumClass[]> = {
  'basic-3': adultBasic3Classes,
  advanced: [...adultAdvancedClasses, ...adultAdvancedExtraClasses],
  masters: adultMastersClasses,
};

export function applyAdultClassOverrides(levels: CurriculumLevel[]) {
  for (const level of levels) {
    const override = adultClassOverrides[level.id];
    if (!override) continue;
    level.classes = override;
  }
}
